   Dictionary<string,object> D(string k,object v){return new Dictionary<string,object>{{k,v}};}
   public Dictionary<string,object> Call(string path,string method,object body){if(path=="/version"){if(VersionOffline)throw new InvalidOperationException("controller unavailable");return D("version","mock");}if(path=="/configs")return D("mode","global");if(path=="/connections")return new Dictionary<string,object>{{"uploadTotal",0},{"downloadTotal",0},{"connections",new object[0]}};
