    if(path=="/proxies"){CatalogReads++;var names=new List<string>{"日本 JP-A","日本 JP-B","新加坡 SG-A","新加坡 SG-B","美国 US-A"};for(int n=0;n<ExtraJapanese;n++)names.Add("日本 JP-C"+n);if(NewMember&&CatalogReads>=3)names.Add("日本 JP-New");var map=new Dictionary<string,object>();foreach(string name in names)map[name]=D("type","Vmess");map["GLOBAL"]=new Dictionary<string,object>{{"type","Selector"},{"now",Selected},{"all",names.Cast<object>().ToArray()}};return D("proxies",map);}throw new InvalidOperationException("unsupported mock request");
