  static void VerifyRuleRepair(){var fake=new RepairFake();var plan=RuleRepair.Prepare(fake);Assert(plan.Ready&&plan.Root=="ChatGPT"&&plan.Child=="节点选择"&&fake.Writes==0,"Rule alignment preview is read-only and identifies existing groups");var applied=RuleRepair.Apply(fake);Assert(applied.Verified&&fake.Root=="节点选择"&&fake.Child=="日本 JP-A"&&fake.Mode=="global","Rule alignment uses global leaf without changing live mode");fake=new RepairFake{FailRoot=true};applied=RuleRepair.Apply(fake);Assert(!applied.Verified&&fake.Root=="新加坡 SG-A"&&fake.Child=="日本 JP-B","Failed rule-path validation restores both original selectors");fake=new RepairFake{ChangeDuringProbe=true};applied=RuleRepair.Apply(fake);Assert(fake.Writes==0&&!applied.Verified,"External mode change cancels prepared rule alignment");fake=new RepairFake{Mode="rule"};plan=RuleRepair.Prepare(fake);Assert(plan.Ready&&plan.Node=="新加坡 SG-A"&&fake.Writes==0,"Rule-mode plan preserves active service node instead of taking GLOBAL node");applied=RuleRepair.Apply(fake);Assert(applied.Verified&&fake.Mode=="rule"&&fake.Root=="节点选择"&&fake.Child=="新加坡 SG-A","Rule-mode repair opens dual-country pool while preserving service leaf and mode");fake=new RepairFake{Mode="rule",FailRoot=true};applied=RuleRepair.Apply(fake);Assert(!applied.Verified&&fake.Root=="新加坡 SG-A"&&fake.Child=="日本 JP-B","Rule-mode repair rolls back both selectors after failed validation");}
  static void VerifyEnhancements(){DateTime now=DateTime.UtcNow;var cfg=new Settings{AutoSwitch=false,RecoveryPauseUntilUtc=now.AddMinutes(10).ToString("o")};Assert(PausePolicy.Active(cfg,now)&&!PausePolicy.Active(cfg,now.AddMinutes(11)),"Temporary recovery pause expires by time");var reloaded=new JavaScriptSerializer().Deserialize<Settings>(new JavaScriptSerializer().Serialize(cfg));Assert(PausePolicy.Active(reloaded,now)&&!reloaded.AutoSwitch,"Temporary pause survives restart without enabling disabled recovery");
