   var area=new Rectangle(-1920,0,1920,1080);var box=FloatGeometry.Place(new Point(-2100,1100),140,false,area);Assert(area.Contains(box)&&box.Left<0,"Floating geometry clamps safely on negative-coordinate monitor");Assert(FloatGeometry.Place(Point.Empty,100,true,new Rectangle(0,0,1920,1080)).Width==184,"Compact floating geometry is smaller");Assert(!FloatGeometry.CoversScreen(new Rectangle(0,0,1920,1040),new Rectangle(0,0,1920,1080))&&FloatGeometry.CoversScreen(new Rectangle(0,0,1920,1080),new Rectangle(0,0,1920,1080)),"Fullscreen detection excludes normal maximized work area");Assert(FloatGeometry.Scale(new Settings{FloatingScale=999})==140&&FloatGeometry.Opacity(new Settings{FloatingOpacity=1})==40,"Invalid appearance values are bounded");
