   d.Observe("SG",false,now,8);d.Observe("SG",true,now.AddSeconds(8),8);d.Observe("SG",false,now.AddSeconds(120),8);Assert(!d.Ready(now.AddSeconds(120),state,true),"Expired intermittent failures cannot trigger a switch");
